import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { 
  X, 
  ArrowDown, 
  Fuel, 
  ShieldCheck, 
  ChevronDown, 
  Info,
  Shuffle,
  Check,
  AlertTriangle,
  User,
  ArrowRight,
  Sparkles,
  Layers,
  Shield,
  Clock,
  Zap,
  Lock,
  EyeOff,
  Settings,
  AlertOctagon,
  Split
} from 'lucide-react';

interface BridgeModalProps {
  isOpen: boolean;
  onClose: () => void;
}

// Helper for tooltips inside the modal
const InfoTooltip = ({ content, title, warning }: { content: string, title?: string, warning?: boolean }) => (
  <div className="group relative flex items-center">
    <Info size={12} className={`${warning ? 'text-amber-500' : 'text-zinc-500'} hover:text-zinc-300 cursor-help transition-colors`} />
    <div className="absolute right-0 top-full mt-2 w-64 p-4 bg-[#111] border border-zinc-800 rounded-xl shadow-[0_10px_40px_-10px_rgba(0,0,0,1)] opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
      {title && <h4 className={`text-[11px] font-bold uppercase tracking-wider mb-1 ${warning ? 'text-amber-500' : 'text-white'}`}>{title}</h4>}
      <p className="text-[10px] text-zinc-400 leading-relaxed font-medium">{content}</p>
    </div>
  </div>
);

const BridgeModal: React.FC<BridgeModalProps> = ({ isOpen, onClose }) => {
  const [mounted, setMounted] = useState(false);

  // Input State
  const [payAmount, setPayAmount] = useState('120000.00'); // Default > 100k to show guardrails

  // 1. Recipient State
  const [recipientMode, setRecipientMode] = useState(false);
  const [recipientAddress, setRecipientAddress] = useState('');

  // 2. Token Choice State
  const [destToken, setDestToken] = useState<'USDC' | 'USDC.e'>('USDC');
  const [isDestTokenSelectorOpen, setIsDestTokenSelectorOpen] = useState(false);

  // 3. Route Selection State
  const [selectedRouteId, setSelectedRouteId] = useState('r1');

  // 4. Execution Policy State
  const [slippage, setSlippage] = useState('0.50'); 
  const [isPrivateTx, setIsPrivateTx] = useState(true); 
  const [confirmedHighRisk, setConfirmedHighRisk] = useState(false); // For Fat Finger Guardrail

  // Constants
  const ETH_ICON = 'https://cryptologos.cc/logos/ethereum-eth-logo.png?v=035';
  const ARB_ICON = 'https://cryptologos.cc/logos/arbitrum-arb-logo.png?v=035';
  const USDC_ICON = 'https://cryptologos.cc/logos/usd-coin-usdc-logo.png?v=035';
  const toChain = 'Arbitrum';

  useEffect(() => {
    setMounted(true);
  }, []);

  // Mock Routes Data with Price Impact
  const routes = useMemo(() => [
    { 
        id: 'r1', 
        provider: 'Stargate V2', 
        protocol: 'LayerZero', 
        time: 12, 
        fee: 250.00, 
        gas: 14.50,
        impact: 0.05, 
        tier: 'TIER 1', 
        tierDesc: 'Institutional',
        tag: 'BEST OVERALL',
    },
    { 
        id: 'r2', 
        provider: 'Across', 
        protocol: 'Optimistic', 
        time: 2, 
        fee: 320.50, 
        gas: 18.20,
        impact: 0.85, // Warning Zone
        tier: 'TIER 1', 
        tierDesc: 'High Security',
        tag: 'FASTEST',
    },
    { 
        id: 'r3', 
        provider: 'Hop', 
        protocol: 'AMB', 
        time: 25, 
        fee: 180.20, 
        gas: 12.10,
        impact: 5.20, // Critical Zone (>5%)
        tier: 'TIER 2', 
        tierDesc: 'Standard',
        tag: 'CHEAPEST',
    },
  ], []);

  const selectedRoute = routes.find(r => r.id === selectedRouteId) || routes[0];

  // --- LOGIC CORE ---
  const payNum = parseFloat(payAmount.replace(/,/g, '')) || 0;
  const slippageNum = parseFloat(slippage) || 0;

  // Financials
  const bridgeFee = selectedRoute.fee;
  const serviceFee = payNum * 0.0005; // 0.05%
  const networkGas = selectedRoute.gas;
  const totalCost = bridgeFee + serviceFee + networkGas;
  const netReceiveAmount = Math.max(0, payNum - totalCost);

  // Guardrail Logic
  const maxSlippageLoss = netReceiveAmount * (slippageNum / 100);
  const worstCaseReceive = netReceiveAmount - maxSlippageLoss;

  const isHighValue = payNum > 100000;
  const isFatFingerRisk = payNum > 50000 && slippageNum > 3.0;
  const isCriticalImpact = selectedRoute.impact > 1.0;
  const needsSplit = selectedRoute.impact > 5.0;

  // Impact Coloring Logic
  const getImpactColor = (val: number) => {
      if (val > 1.0) return 'text-rose-500';
      if (val > 0.3) return 'text-amber-500';
      return 'text-emerald-500';
  };

  const getImpactBg = (val: number) => {
      if (val > 1.0) return 'bg-rose-500/10 border-rose-500/20';
      if (val > 0.3) return 'bg-amber-500/10 border-amber-500/20';
      return 'bg-emerald-500/10 border-emerald-500/20';
  };

  if (!mounted) return null;

  const portalRoot = document.getElementById('portal-root') || document.body;

  return createPortal(
    <div className={`fixed inset-0 z-[9999] flex items-center justify-center p-4 transition-all duration-300 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>

      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/80 backdrop-blur-md transition-opacity duration-300"
        onClick={onClose}
      />

      {/* Modal Content */}
      <div className={`relative w-full max-w-[1200px] h-[90vh] bg-[#09090b] border border-white/10 rounded-[2rem] shadow-2xl overflow-hidden transition-all duration-500 transform ${isOpen ? 'scale-100 translate-y-0 opacity-100' : 'scale-95 translate-y-8 opacity-0'} flex flex-col`}>

        {/* Header */}
        <div className="px-8 pt-6 pb-4 border-b border-white/5 flex items-center justify-between bg-zinc-900/50 backdrop-blur-md shrink-0">
            <div className="flex items-center gap-3">
                <div className="bg-emerald-500/10 p-2 rounded-xl border border-emerald-500/20">
                    <Shuffle className="text-emerald-500" size={20} /> 
                </div>
                <div>
                    <h2 className="text-lg font-black text-white tracking-tight leading-none">INSTITUTIONAL BRIDGE</h2>
                    <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mt-1">Cross-Chain Aggregation</p>
                </div>
            </div>
            <button 
                onClick={onClose}
                className="p-2 text-zinc-500 hover:text-white transition-colors bg-zinc-900/50 rounded-lg hover:bg-zinc-800"
            >
                <X size={18} />
            </button>
        </div>

        {/* MAIN SPLIT VIEW */}
        <div className="flex-1 overflow-y-auto scrollbar-hide p-8 bg-[#050505]">
            <div className="grid grid-cols-1 lg:grid-cols-10 gap-8 items-start h-full">

                {/* --- LEFT PANEL: CONFIGURATION & POLICY --- */}
                <div className="lg:col-span-4 flex flex-col gap-6">

                    {/* BLOCK 1: CONFIGURATION (Intent) */}
                    <div className="bg-zinc-900/40 border border-white/5 rounded-2xl p-5 space-y-6 shadow-xl backdrop-blur-sm relative">
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Transfer Details</span>
                        </div>

                        {/* From Section */}
                        <div className="space-y-4">
                            <div className="flex justify-between items-start">
                                <div className="flex flex-col gap-2 w-full">
                                     <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest flex justify-between w-full pr-1">
                                        <span>From Network</span>
                                        <span className="font-mono text-zinc-500">Bal: 142,000.00</span>
                                     </label>
                                     <div className="flex items-center gap-3">
                                        <input 
                                            type="text" 
                                            value={payAmount}
                                            onChange={(e) => setPayAmount(e.target.value)}
                                            className="text-3xl lg:text-4xl font-mono font-medium tracking-tighter bg-transparent outline-none placeholder:text-zinc-800 text-white w-full min-w-0" 
                                            placeholder="0.00" 
                                        />
                                        <div className="flex flex-col gap-1 shrink-0">
                                            <button className="flex items-center gap-2 bg-zinc-950/50 border border-white/10 px-2 py-1.5 rounded-lg hover:border-white/20 transition-colors w-full justify-between">
                                                <div className="flex items-center gap-1.5">
                                                    <img src={ETH_ICON} className="w-3.5 h-3.5 object-contain" alt="ETH" />
                                                    <span className="font-bold text-white text-[10px]">Ethereum</span>
                                                </div>
                                                <ChevronDown size={10} className="text-zinc-600" />
                                            </button>
                                            <button className="flex items-center gap-2 bg-zinc-950/50 border border-white/10 px-3 py-2 rounded-xl hover:border-white/20 transition-colors">
                                                <img src={USDC_ICON} className="w-5 h-5 object-contain" alt="USDC" />
                                                <span className="font-bold text-white text-sm">USDC</span>
                                                <ChevronDown size={12} className="text-zinc-600" />
                                            </button>
                                        </div>
                                     </div>
                                </div>
                            </div>

                            {/* Connector */}
                            <div className="relative h-px bg-white/5 w-full my-2">
                                <div className="absolute left-1/2 -translate-x-1/2 -top-3 p-1.5 bg-[#0e0e11] border border-white/10 rounded-full text-zinc-500 shadow-sm">
                                    <ArrowDown size={12} />
                                </div>
                            </div>

                            {/* To Section */}
                            <div className="flex justify-between items-end">
                                <div className="flex flex-col gap-2 w-full">
                                     <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">To Network</label>
                                     <div className="flex items-center gap-3">
                                        <div className="flex flex-col w-full min-w-0">
                                            <div className="text-3xl lg:text-4xl font-mono font-medium tracking-tighter text-zinc-300 truncate">
                                                {netReceiveAmount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                                            </div>
                                            <div className="text-xs font-mono font-bold text-zinc-600 mt-1">
                                                Net after fees
                                            </div>
                                        </div>
                                        <div className="flex flex-col gap-1 shrink-0 relative">
                                            <button className="flex items-center gap-2 bg-zinc-950/50 border border-white/10 px-2 py-1.5 rounded-lg hover:border-white/20 transition-colors w-full justify-between">
                                                <div className="flex items-center gap-1.5">
                                                    <img src={ARB_ICON} className="w-3.5 h-3.5 object-contain" alt="ARB" />
                                                    <span className="font-bold text-white text-[10px]">Arbitrum</span>
                                                </div>
                                                <ChevronDown size={10} className="text-zinc-600" />
                                            </button>

                                            {/* Token Selector */}
                                            <div className="relative">
                                                <button 
                                                    onClick={() => setIsDestTokenSelectorOpen(!isDestTokenSelectorOpen)}
                                                    className="flex items-center gap-2 bg-zinc-950/50 border border-white/5 px-3 py-2 rounded-xl hover:border-white/10 transition-colors self-start w-full justify-between min-w-[110px]"
                                                >
                                                    <div className="flex items-center gap-2">
                                                        <img src={USDC_ICON} className="w-5 h-5 object-contain" alt="USDC" />
                                                        <span className="font-bold text-white text-sm">{destToken}</span>
                                                    </div>
                                                    <ChevronDown size={12} className={`text-zinc-600 transition-transform ${isDestTokenSelectorOpen ? 'rotate-180' : ''}`} />
                                                </button>
                                                {isDestTokenSelectorOpen && (
                                                    <div className="absolute right-0 top-full mt-1 w-48 bg-[#1a1a1a] border border-white/10 rounded-xl shadow-xl z-50 overflow-hidden animate-in fade-in zoom-in-95">
                                                        <button onClick={() => { setDestToken('USDC'); setIsDestTokenSelectorOpen(false); }} className="w-full text-left px-3 py-2.5 hover:bg-white/5 flex items-center justify-between group">
                                                            <div className="flex flex-col"><span className="text-xs font-bold text-white">USDC</span><span className="text-[9px] text-zinc-500 uppercase font-black tracking-wider group-hover:text-emerald-500">Native</span></div>
                                                            {destToken === 'USDC' && <Check size={12} className="text-emerald-500" />}
                                                        </button>
                                                        <button onClick={() => { setDestToken('USDC.e'); setIsDestTokenSelectorOpen(false); }} className="w-full text-left px-3 py-2.5 hover:bg-white/5 flex items-center justify-between group">
                                                            <div className="flex flex-col"><span className="text-xs font-bold text-white">USDC.e</span><span className="text-[9px] text-zinc-500 uppercase font-black tracking-wider group-hover:text-amber-500">Bridged</span></div>
                                                            {destToken === 'USDC.e' && <Check size={12} className="text-emerald-500" />}
                                                        </button>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                     </div>
                                </div>
                            </div>

                            {/* Recipient */}
                            <div className="pt-4 mt-2 border-t border-white/5">
                                <div className="flex justify-between items-center mb-2">
                                    <div 
                                        className="flex items-center gap-2 cursor-pointer group"
                                        onClick={() => setRecipientMode(!recipientMode)}
                                    >
                                        <div className={`w-4 h-4 rounded border flex items-center justify-center transition-colors ${recipientMode ? 'bg-emerald-500 border-emerald-500' : 'border-zinc-700 bg-zinc-900'}`}>
                                            {recipientMode && <Check size={10} className="text-black stroke-[4px]" />}
                                        </div>
                                        <span className="text-[10px] font-bold text-zinc-500 group-hover:text-zinc-300 uppercase tracking-wide">Custom Recipient</span>
                                    </div>
                                </div>
                                {recipientMode ? (
                                    <div className="mt-2 animate-in fade-in slide-in-from-top-2">
                                        <div className="relative">
                                            <input type="text" value={recipientAddress} onChange={(e) => setRecipientAddress(e.target.value)} placeholder="Enter 0x Address or ENS" className="w-full bg-[#050505] border border-amber-500/30 rounded-xl py-2.5 pl-9 pr-4 text-xs font-mono text-white focus:outline-none focus:border-amber-500" />
                                            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-600"><User size={12} /></div>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="mt-1 pl-6">
                                        <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-zinc-800/50 border border-white/5">
                                            <User size={10} className="text-zinc-400" />
                                            <span className="text-[10px] text-zinc-500 font-medium uppercase tracking-wider">Recipient: <span className="text-white font-bold">Alex K.</span> (Self)</span>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* BLOCK 2: EXECUTION POLICY (Safety) */}
                    <div className="bg-zinc-900/20 border border-white/5 rounded-2xl p-5 shadow-inner">
                        <div className="flex items-center justify-between mb-4">
                            <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-2">
                                <Shield size={12} className="text-zinc-500"/> Risk Parameters
                            </span>
                        </div>

                        <div className="flex flex-col space-y-4">

                            {/* MEV Toggle */}
                            <div className="flex items-center justify-between">
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-bold text-zinc-300 uppercase tracking-wide">MEV Protection</span>
                                    <span className="text-[9px] text-zinc-500">Flashbots / Private RPC</span>
                                </div>
                                <button 
                                    onClick={() => setIsPrivateTx(!isPrivateTx)}
                                    className={`w-10 h-5 rounded-full relative transition-colors ${isPrivateTx ? 'bg-emerald-500' : 'bg-zinc-700'}`}
                                >
                                    <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all duration-200 ${isPrivateTx ? 'left-6' : 'left-1'}`}></div>
                                </button>
                            </div>

                            {/* MEV Warning Guardrail */}
                            {isHighValue && !isPrivateTx && (
                                <div className="p-2.5 bg-rose-500/10 border border-rose-500/20 rounded-lg flex items-start gap-2 animate-in fade-in">
                                    <AlertOctagon size={12} className="text-rose-500 shrink-0 mt-0.5" />
                                    <p className="text-[9px] text-rose-400 font-bold leading-relaxed">
                                        CRITICAL: Volume &gt; $100k without MEV Shield exposes trade to sandwich attacks. Enable protection recommended.
                                    </p>
                                </div>
                            )}

                            {/* Slippage Control */}
                            <div className="grid grid-cols-2 gap-4 pt-2 border-t border-white/5">
                                <div>
                                    <label className="text-[9px] font-bold text-zinc-500 uppercase tracking-wide block mb-1">Slippage Tolerance</label>
                                    <div className="relative">
                                        <input 
                                            type="number" 
                                            value={slippage}
                                            onChange={(e) => setSlippage(e.target.value)}
                                            className={`w-full bg-[#050505] border ${slippageNum > 3 ? 'border-amber-500 text-amber-500' : 'border-white/10 text-white'} rounded-lg py-2 pl-3 pr-6 text-xs font-mono font-bold focus:outline-none`}
                                        />
                                        <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-bold text-zinc-600">%</span>
                                    </div>
                                </div>
                                <div>
                                    <label className="text-[9px] font-bold text-zinc-500 uppercase tracking-wide block mb-1">Slippage Limit ($)</label>
                                    <div className="w-full bg-zinc-900/50 border border-white/5 rounded-lg py-2 px-3 text-xs font-mono font-bold text-rose-400">
                                        -${maxSlippageLoss.toLocaleString('en-US', {maximumFractionDigits: 0})}
                                    </div>
                                </div>
                            </div>

                            {/* Fat Finger Guardrail */}
                            {isFatFingerRisk && (
                                <div className="p-3 bg-amber-500/10 border border-amber-500/20 rounded-lg space-y-2 animate-in fade-in">
                                    <div className="flex items-center gap-2 text-amber-500">
                                        <AlertTriangle size={14} />
                                        <span className="text-[10px] font-black uppercase tracking-wide">High Slippage Alert</span>
                                    </div>
                                    <p className="text-[9px] text-zinc-400 leading-relaxed">
                                        You are allowing <span className="text-amber-500 font-bold">{slippage}%</span> slippage on a ${payNum.toLocaleString()} trade. Potential loss: <span className="text-rose-500 font-bold">-${maxSlippageLoss.toLocaleString()}</span>.
                                    </p>
                                    <label className="flex items-center gap-2 cursor-pointer mt-2">
                                        <input type="checkbox" checked={confirmedHighRisk} onChange={(e) => setConfirmedHighRisk(e.target.checked)} className="rounded bg-zinc-900 border-zinc-700 accent-amber-500" />
                                        <span className="text-[9px] font-bold text-zinc-300">I confirm I understand the risks</span>
                                    </label>
                                </div>
                            )}

                        </div>
                    </div>

                    {/* BLOCK 3: SIMULATION & CTA */}
                    <div className="bg-zinc-900/20 border border-white/5 rounded-2xl p-5 shadow-inner">
                        <div className="flex flex-col space-y-3 mb-6">
                            <div className="flex justify-between items-center pb-3 border-b border-dashed border-white/10">
                                <span className="text-[10px] font-medium text-zinc-500 uppercase tracking-widest flex items-center gap-1">
                                    <Fuel size={10} /> Network Gas
                                </span>
                                <span className="text-xs font-mono font-bold text-white">~${selectedRoute.gas.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between items-center pb-3 border-b border-dashed border-white/10">
                                <span className="text-[10px] font-medium text-zinc-500 uppercase tracking-widest flex items-center gap-1">
                                    <Sparkles size={10} /> Service Fee (0.05%)
                                </span>
                                <span className="text-xs font-mono font-bold text-white">~${serviceFee.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between items-center pt-1">
                                <span className="text-[10px] font-medium text-zinc-500 uppercase tracking-widest">Est. Time</span>
                                <span className="text-white font-bold text-xs">~{selectedRoute.time}m</span>
                            </div>
                        </div>

                        {/* Dynamic CTA */}
                        <div className="relative group">
                            <button 
                                disabled={isFatFingerRisk && !confirmedHighRisk}
                                className={`w-full h-14 rounded-xl font-black text-[11px] uppercase tracking-[0.1em] transition-all shadow-xl active:scale-[0.98] flex items-center justify-center gap-2 ${
                                    (isFatFingerRisk && !confirmedHighRisk) 
                                    ? 'bg-zinc-800 text-zinc-600 cursor-not-allowed border border-white/5' 
                                    : isCriticalImpact 
                                        ? 'bg-zinc-700 text-white border border-rose-500/50 hover:bg-zinc-600 hover:border-rose-500' // Neutralized color for dangerous impact
                                        : 'bg-emerald-600 text-white hover:bg-emerald-500 shadow-emerald-500/10'
                                }`}
                            >
                                {isPrivateTx && <EyeOff size={14} className={isCriticalImpact ? 'text-white' : 'text-emerald-200'} />}
                                <span>REVIEW TRANSACTION</span>
                                <ArrowRight size={14} />
                            </button>
                        </div>
                    </div>

                </div>

                {/* --- RIGHT PANEL: ROUTE ANALYSIS (High Fidelity) --- */}
                <div className="lg:col-span-6 bg-zinc-900/40 border border-white/5 rounded-2xl p-6 flex flex-col h-full overflow-y-auto scrollbar-thin scrollbar-thumb-zinc-800 scrollbar-track-transparent">

                    <div className="flex justify-between items-start mb-8 shrink-0">
                        <div className="flex items-center gap-2">
                            <h2 className="text-lg font-bold text-white flex items-center gap-2">
                                <Sparkles className="w-5 h-5 text-gray-500" />
                                Route Analysis
                            </h2>
                            <InfoTooltip title="Aggregation Logic" content="Routes are aggregated from 12+ bridges. Selection prioritizes liquidity depth (Low Price Impact) and security audits." />
                        </div>
                    </div>

                    <div className="flex flex-col h-full gap-4">
                        <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest pl-1">Route Options</span>

                        {/* ROUTE LIST */}
                        <div className="space-y-3">
                            {routes.map((route) => {
                                const isSelected = selectedRouteId === route.id;
                                const impactColor = getImpactColor(route.impact);
                                const impactBg = getImpactBg(route.impact);

                                return (
                                    <div 
                                        key={route.id}
                                        onClick={() => setSelectedRouteId(route.id)}
                                        className={`relative p-5 rounded-xl border cursor-pointer transition-all group overflow-hidden ${
                                            isSelected 
                                            ? 'bg-zinc-800/80 border-emerald-500/50 shadow-lg shadow-emerald-500/5' 
                                            : 'bg-black/20 border-white/5 hover:bg-zinc-800/40 hover:border-white/10'
                                        }`}
                                    >
                                        {/* Selection Indicator */}
                                        {isSelected && (
                                            <div className="absolute left-0 top-0 bottom-0 w-1 bg-emerald-500"></div>
                                        )}

                                        {/* Header: Provider + Tier Badge */}
                                        <div className="flex justify-between items-start mb-4">
                                            <div className="flex items-center gap-3">
                                                {/* Icon Mock */}
                                                <div className="w-8 h-8 rounded-lg bg-zinc-900 border border-white/10 flex items-center justify-center">
                                                    <Layers size={14} className="text-zinc-400" />
                                                </div>
                                                <div className="flex flex-col">
                                                    <div className="text-sm font-bold text-white flex items-center gap-2">
                                                        {route.provider}
                                                        {isSelected && <CheckCircle size={12} className="text-emerald-500" />}
                                                    </div>
                                                    <div className="text-[10px] text-zinc-500 font-mono">
                                                        via <span className="text-zinc-400">{route.protocol}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Tier Badge inside card */}
