                                                        -{route.impact.toFixed(2)}%
                                                    </span>
                                                    {route.impact > 1 && <AlertTriangle size={14} className="text-rose-500" />}
                                                </div>
                                            </div>

                                            {/* Bridge & Gas Fees */}
                                            <div className="col-span-3">
                                                <p className="text-[9px] text-zinc-500 font-bold uppercase mb-1">Bridge & Gas Fees</p>
                                                <p className="text-xs font-mono font-bold text-white">~${(route.fee + route.gas).toFixed(2)}</p>
                                            </div>

                                            {/* Time */}
                                            <div className="col-span-3">
                                                <p className="text-[9px] text-zinc-500 font-bold uppercase mb-1">Est. Time</p>
                                                <div className="flex items-center gap-1.5">
                                                    <Clock size={10} className="text-zinc-600" />
                                                    <p className={`text-xs font-mono font-bold ${route.time < 10 ? 'text-emerald-400' : 'text-white'}`}>~{route.time} Min</p>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Split Trade Suggestion */}
                                        {route.impact > 5 && isSelected && (
                                            <div className="mt-4 ml-11 p-2 bg-blue-500/10 border border-blue-500/20 rounded-lg flex items-center gap-2 animate-in fade-in">
                                                <Split size={14} className="text-blue-400" />
                                                <span className="text-[10px] font-bold text-blue-300">Liquidity limited. Recommendation: Split into 3 tranches.</span>
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>

                    </div>
                </div>

            </div>
        </div>

      </div>
    </div>,
    portalRoot
  );
};

