                                <span className="text-xs font-mono font-bold text-white">-{selectedRoute.impact}%</span>
                            </div>
                            <div className="flex justify-between items-center pb-2 border-b border-dashed border-white/10">
                                <span className="text-[10px] font-medium text-zinc-500 uppercase tracking-widest flex items-center gap-1">
                                    <Fuel size={10} /> Network Gas
                                </span>
                                <span className="text-xs font-mono font-bold text-white">~${selectedRoute.gas.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between items-center pb-2 border-b border-dashed border-white/10">
                                <span className="text-[10px] font-medium text-zinc-500 uppercase tracking-widest flex items-center gap-1">
                                    <Sparkles size={10} /> Service Fee (0.05%)
                                </span>
                                <span className="text-xs font-mono font-bold text-white">~${serviceFee.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between items-center pt-1">
                                <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Total Cost</span>
                                <span className="text-white font-bold font-mono text-sm">~${totalCost.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</span>
                            </div>
                        </div>

                        {/* Dynamic CTA */}
                        <div className="relative group">
                            <button 
                                className={`w-full h-14 rounded-xl font-black text-[11px] uppercase tracking-[0.1em] transition-all shadow-xl active:scale-[0.98] flex items-center justify-center gap-2 ${
                                    isCriticalImpact 
                                        ? 'bg-zinc-700 text-white border border-rose-500/50 hover:bg-zinc-600 hover:border-rose-500' // Neutralized color for dangerous impact
                                        : 'bg-emerald-600 text-white hover:bg-emerald-500 shadow-emerald-500/10'
                                }`}
                            >
                                {isPrivateTx && <EyeOff size={14} className={isCriticalImpact ? 'text-white' : 'text-emerald-200'} />}
                                <span>REVIEW TRANSACTION</span>
                            </button>
                        </div>
                    </div>

                </div>

                {/* --- RIGHT PANEL: ROUTE ANALYSIS (High Fidelity) --- */}
                <div className="lg:col-span-6 bg-zinc-900/40 border border-white/5 rounded-2xl p-6 flex flex-col h-full overflow-y-auto scrollbar-thin scrollbar-thumb-zinc-800 scrollbar-track-transparent">

                    <div className="flex justify-between items-start mb-8 shrink-0">
                        <div className="flex items-center gap-2">
                            <h2 className="text-lg font-bold text-white flex items-center gap-2">
                                <Sparkles className="w-5 h-5 text-gray-500" />
                                Route Analysis
                            </h2>
                            <InfoTooltip title="Aggregation Logic" content="Routes are aggregated from 12+ bridges. Selection prioritizes liquidity depth (Low Price Impact) and security audits." />
                        </div>
                    </div>

                    <div className="flex flex-col h-full gap-4">
                        <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest pl-1">Route Options</span>

                        {/* ROUTE LIST */}
                        <div className="space-y-3">
                            {routes.map((route) => {
                                const isSelected = selectedRouteId === route.id;

                                return (
                                    <div 
                                        key={route.id}
                                        onClick={() => setSelectedRouteId(route.id)}
                                        className={`relative p-5 rounded-xl border cursor-pointer transition-all group overflow-hidden ${
                                            isSelected 
                                            ? 'bg-zinc-800/80 border-emerald-500/50 shadow-lg shadow-emerald-500/5' 
                                            : 'bg-black/20 border-white/5 hover:bg-zinc-800/40 hover:border-white/10'
                                        }`}
                                    >
                                        {/* Selection Indicator */}
                                        {isSelected && (
                                            <div className="absolute left-0 top-0 bottom-0 w-1 bg-emerald-500"></div>
                                        )}

                                        {/* Header: Provider + Description */}
                                        <div className="flex justify-between items-start mb-4">
                                            <div className="flex items-center gap-3">
                                                <div className="flex flex-col">
                                                    <div className="text-sm font-bold text-white flex items-center gap-2">
                                                        {route.provider}
                                                        {isSelected && <CheckCircle size={12} className="text-emerald-500" />}
                                                    </div>
                                                    <div className="text-[10px] text-zinc-500 font-mono">
                                                        via <span className="text-zinc-400">{route.protocol}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex flex-col items-end gap-1">
                                                <span className="text-[9px] font-bold text-zinc-500">{route.tierDesc}</span>
                                            </div>
                                        </div>

                                        {/* Trade-off Triangle (Ratings) - REPLACES BADGES */}
                                        <div className="grid grid-cols-3 gap-4 mb-4 bg-zinc-900/30 p-2 rounded-lg border border-white/5">
                                            <RatingBar label="SPEED" value={route.ratings.speed} />
                                            <RatingBar label="COST" value={route.ratings.cost} />
                                            <RatingBar label="SECURITY" value={route.ratings.security} />
                                        </div>

                                        {/* Detailed Cost Breakdown - FIXED DATA INCONSISTENCY */}
                                        <div className="space-y-1.5 pl-1">
                                            <div className="flex justify-between items-center">
                                                <span className="text-[9px] text-zinc-500 font-bold uppercase">Price Impact</span>
                                                <span className={`text-[10px] font-mono font-bold ${route.impact > 1 ? 'text-rose-500' : 'text-zinc-400'}`}>-{route.impact}%</span>
                                            </div>
                                            <div className="flex justify-between items-center">
                                                <span className="text-[9px] text-zinc-500 font-bold uppercase">Bridge Fee</span>
                                                <span className="text-[10px] font-mono font-bold text-zinc-400">~${route.fee.toFixed(2)}</span>
                                            </div>
                                            <div className="flex justify-between items-center">
                                                <span className="text-[9px] text-zinc-500 font-bold uppercase">Network Gas</span>
                                                <span className="text-[10px] font-mono font-bold text-zinc-400">~${route.gas.toFixed(2)}</span>
                                            </div>

                                            {/* Divider */}
                                            <div className="h-px bg-white/5 my-1"></div>

                                            <div className="flex justify-between items-center pt-1">
                                                <div className="flex flex-col">
                                                    <span className="text-[9px] text-zinc-400 font-black uppercase tracking-wider">Total Cost</span>
                                                    <span className="text-[8px] text-zinc-600 font-medium">Excl. Service Fee</span>
                                                </div>
                                                <div className="flex flex-col items-end">
                                                    <span className="text-xs font-mono font-bold text-white">~${(route.fee + route.gas).toFixed(2)}</span>
                                                    <span className="text-[9px] font-mono text-zinc-500 flex items-center gap-1">
                                                        <Clock size={8} /> ~{route.time} Min
                                                    </span>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Split Trade Suggestion */}
                                        {route.impact > 5 && isSelected && (
                                            <div className="mt-4 p-2 bg-blue-500/10 border border-blue-500/20 rounded-lg flex items-center gap-2 animate-in fade-in">
                                                <Split size={14} className="text-blue-400" />
                                                <span className="text-[10px] font-bold text-blue-300">Liquidity limited. Recommendation: Split into 3 tranches.</span>
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>

                    </div>
                </div>

            </div>
        </div>

      </div>
    </div>,
    portalRoot
  );
};

// Simple icon wrapper to fix missing import
const CheckCircle = ({ size, className }: { size: number, className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
);

export default BridgeModal;

import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { 
  X, 
  ArrowDown, 
  Fuel, 
  ChevronDown, 
  Info,
  Check,
  User,
  Sparkles,
  Clock,
  EyeOff,
  AlertOctagon,
  Edit2,
  Undo2,
  Split
} from 'lucide-react';

interface BridgeModalProps {
  isOpen: boolean;
  onClose: () => void;
}

// Helper for tooltips inside the modal
const InfoTooltip = ({ content, title, warning }: { content: string, title?: string, warning?: boolean }) => (
  <div className="group relative flex items-center">
    <Info size={12} className={`${warning ? 'text-amber-500' : 'text-zinc-500'} hover:text-zinc-300 cursor-help transition-colors`} />
    <div className="absolute right-0 top-full mt-2 w-64 p-4 bg-[#111] border border-zinc-800 rounded-xl shadow-[0_10px_40px_-10px_rgba(0,0,0,1)] opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
      {title && <h4 className={`text-[11px] font-bold uppercase tracking-wider mb-1 ${warning ? 'text-amber-500' : 'text-white'}`}>{title}</h4>}
      <p className="text-[10px] text-zinc-400 leading-relaxed font-medium">{content}</p>
    </div>
  </div>
);

const RatingBar = ({ label, value }: { label: string, value: number }) => (
    <div className="flex flex-col gap-1 w-full">
        <div className="flex justify-between items-end">
            <span className="text-[8px] font-bold text-zinc-500 uppercase tracking-wider">{label}</span>
            <span className="text-[8px] font-mono text-zinc-400">{value}/10</span>
        </div>
        <div className="h-1 bg-zinc-800 rounded-full overflow-hidden w-full">
            <div 
                className={`h-full rounded-full ${value >= 8 ? 'bg-emerald-500' : value >= 5 ? 'bg-amber-500' : 'bg-rose-500'}`} 
                style={{ width: `${value * 10}%` }}
            ></div>
        </div>
    </div>
);

const BridgeModal: React.FC<BridgeModalProps> = ({ isOpen, onClose }) => {
  const [mounted, setMounted] = useState(false);

  // Input State
  const [payAmount, setPayAmount] = useState('120000.00'); 

  // 1. Recipient State
  const [isEditingRecipient, setIsEditingRecipient] = useState(false);
  const [recipientAddress, setRecipientAddress] = useState('0x71C...4f92 (Vault)');

  // 2. Token Choice State
  const [destToken, setDestToken] = useState<'USDC' | 'USDC.e'>('USDC');
  const [isDestTokenSelectorOpen, setIsDestTokenSelectorOpen] = useState(false);

  // 3. Route Selection State
  const [selectedRouteId, setSelectedRouteId] = useState('r1');

  // 4. Execution Policy State
  const [slippage, setSlippage] = useState('0.50'); 
  const [isPrivateTx, setIsPrivateTx] = useState(true); 

  // Constants
  const ETH_ICON = 'https://cryptologos.cc/logos/ethereum-eth-logo.png?v=035';
  const ARB_ICON = 'https://cryptologos.cc/logos/arbitrum-arb-logo.png?v=035';
  const USDC_ICON = 'https://cryptologos.cc/logos/usd-coin-usdc-logo.png?v=035';

  useEffect(() => {
    setMounted(true);
  }, []);

  // Updated Mock Routes Data with Ratings and Concrete Data
  const routes = useMemo(() => [
    { 
        id: 'r1', 
        provider: 'Stargate V2', 
        protocol: 'LayerZero', 
        time: 12, 
        fee: 250.00, 
        gas: 14.50,
        impact: 0.05, 
        ratings: { speed: 6, cost: 8, security: 10 },
        tierDesc: 'Institutional',
    },
    { 
        id: 'r2', 
        provider: 'Across', 
        protocol: 'Optimistic', 
        time: 2, 
        fee: 320.50, 
        gas: 18.20,
        impact: 0.85, 
        ratings: { speed: 10, cost: 6, security: 9 },
        tierDesc: 'High Security',
    },
    { 
        id: 'r3', 
        provider: 'Hop', 
        protocol: 'AMB', 
        time: 25, 
        fee: 180.20, 
        gas: 12.10,
        impact: 5.20, 
        ratings: { speed: 4, cost: 9, security: 7 },
        tierDesc: 'Standard',
    },
  ], []);

  const selectedRoute = routes.find(r => r.id === selectedRouteId) || routes[0];

  // --- LOGIC CORE ---
  const payNum = parseFloat(payAmount.replace(/,/g, '')) || 0;
  const slippageNum = parseFloat(slippage) || 0;

  // Financials
  const bridgeFee = selectedRoute.fee;
  const serviceFee = payNum * 0.0005; // 0.05%
  const networkGas = selectedRoute.gas;

  // Refactored Total Cost Logic: Sum of all fees
  const totalCost = bridgeFee + serviceFee + networkGas;

  // Max Loss Calculation: Total Cost + Slippage Value
  const slippageValue = payNum * (slippageNum / 100);
  const maxAllowedLoss = totalCost + slippageValue;

  const netReceiveAmount = Math.max(0, payNum - totalCost);

  // Critical Impact Logic
  const isCriticalImpact = selectedRoute.impact > 1.0;

  if (!mounted) return null;

  const portalRoot = document.getElementById('portal-root') || document.body;

  return createPortal(
    <div className={`fixed inset-0 z-[9999] flex items-center justify-center p-4 transition-all duration-300 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>

      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/80 backdrop-blur-md transition-opacity duration-300"
        onClick={onClose}
      />

      {/* Modal Content - Fitted Height */}
      <div className={`relative w-full max-w-[1200px] bg-[#09090b] border border-white/10 rounded-[2rem] shadow-2xl overflow-hidden transition-all duration-500 transform flex flex-col max-h-[95vh] ${isOpen ? 'scale-100 translate-y-0 opacity-100' : 'scale-95 translate-y-8 opacity-0'}`}>

        {/* Header - Compact */}
        <div className="px-6 py-4 border-b border-white/5 flex items-center justify-between bg-zinc-900/50 backdrop-blur-md shrink-0">
            <div className="flex items-center gap-3">
                <div>
                    <h2 className="text-base font-black text-white tracking-tight leading-none">INSTITUTIONAL BRIDGE</h2>
                    <p className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mt-0.5">Cross-Chain Aggregation</p>
                </div>
            </div>
            <button 
                onClick={onClose}
                className="p-1.5 text-zinc-500 hover:text-white transition-colors bg-zinc-900/50 rounded-lg hover:bg-zinc-800"
            >
                <X size={16} />
            </button>
        </div>

        {/* MAIN SPLIT VIEW - Compact Padding */}
        <div className="flex-1 overflow-hidden p-6 bg-[#050505]">
            <div className="grid grid-cols-1 lg:grid-cols-10 gap-6 items-start h-full">

